Nat4	loadPersistents_MySelectWindow(V_Environment environment);
Nat4	loadPersistents_MySelectWindow(V_Environment environment)
{
	V_Value tempPersistent = NULL;
	V_Dictionary dictionary = environment->persistentsTable;

	tempPersistent = create_persistentNode("VPLSelect Window/Toolbar",NULL,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	return kNOERROR;

}

Nat4	load_MySelectWindow(V_Environment environment);
Nat4	load_MySelectWindow(V_Environment environment)
{

	loadClasses_MySelectWindow(environment);
	loadUniversals_MySelectWindow(environment);
	loadPersistents_MySelectWindow(environment);
	return kNOERROR;

}

